// GENERATED by scripts/bundle-functions.mjs — do not edit by hand.
// Edit supabase/functions/_shared/* and <fn>/source.ts, then re-run the bundler.

// ---------------------------------------------------------------------------
// WorkSense constrained staffing planner — pure, deterministic core.
// Replaces the fixed comparison with an explicit scenario model:
//  - skill-by-skill capability (never a scalar union)
//  - separate CURRENT verified coverage vs CONDITIONAL future coverage
//  - mandatory-skill gates before any option is "ready"
//  - sequential/parallel stages with the ACTUAL latest finish (never clamped)
//  - status vocabulary: feasible | conditional | infeasible | insufficient_data
//  - explicit candidate filtering (reject/expire/stale rules)
// Zero LLM — the model may only narrate the numbers this engine produces.
// ---------------------------------------------------------------------------

export type PlannerStatus = "feasible" | "conditional" | "infeasible" | "insufficient_data";

export interface RequiredSkill {
  skill: string;
  min_proficiency: number;
  mandatory: boolean;
}

export interface ScenarioInput {
  name: string;
  demand_title: string;
  department?: string;
  required_skills: RequiredSkill[];
  capacity_people: number;
  deadline_days: number;
  budget_usd: number;
  geography?: string;
  horizon_months: number;
  assumptions_version: string;
}

export interface PersonSkill {
  name: string;
  proficiency: number;
  verification_rigor: "low" | "medium" | "high";
}

export interface Person {
  id: string;
  name: string;
  department?: string | null;
  manager_id?: string | null;
  current_assignment?: string | null; // non-null critical project => not available
  skills: PersonSkill[];
}

export interface Candidate {
  id: string;
  name: string;
  status: string; // active | invited | rejected | expired | ...
  applied_at?: string;
  match_score?: number | null;
  skills: PersonSkill[];
}

export interface Assumptions {
  version: string;
  hire_lead_days: number;
  hire_cost_usd: number;
  move_transition_days: number; // handover + transfer
  move_cost_usd: number;
  manager_approval_days: number;
  training_days_per_skill: number; // sequential per skill
  training_cost_usd_per_skill: number;
  verification_days: number;
  candidate_stale_days: number; // applied_at older than this => stale, excluded
}

export const DEFAULT_ASSUMPTIONS: Assumptions = {
  version: "v1",
  hire_lead_days: 56,
  hire_cost_usd: 45000,
  move_transition_days: 14,
  move_cost_usd: 6000,
  manager_approval_days: 5,
  training_days_per_skill: 21,
  training_cost_usd_per_skill: 1200,
  verification_days: 7,
  candidate_stale_days: 180,
};

export type CoverageKind = "verified" | "conditional" | "gap" | "absent";

export interface SkillCoverageRow {
  skill: string;
  min_proficiency: number;
  mandatory: boolean;
  coverage: CoverageKind;
  current_proficiency: number | null;
  projected_proficiency: number | null;
  source: string;
  mandatory_satisfied: boolean;
}

export interface Stage {
  name: string;
  kind: "hire" | "approval" | "handover" | "training" | "verification" | "transition";
  duration_days: number;
  parallel: boolean;
}

export interface OptionResult {
  id: string;
  label: string;
  status: PlannerStatus;
  status_reason: string;
  skill_coverage: SkillCoverageRow[];
  verified_coverage_pct: number; // of REQUIRED skills covered by CURRENT verified skills
  conditional_coverage_pct: number; // coverage only after conditions (training/verification/hire)
  mandatory_satisfied: boolean;
  mandatory_missing: string[];
  timeline: Stage[];
  ready_at_days: number; // actual latest finish, never clamped to deadline
  meets_deadline: boolean;
  cost_usd: number;
  budget_satisfied: boolean;
  dependency_risk: "low" | "medium" | "high";
  constraints_satisfied: string[];
  constraints_violated: string[];
  rationale: string; // why this satisfies + why alternatives fail
  subject?: string; // chosen person / candidate name
}

export interface PlanResult {
  scenario: ScenarioInput;
  assumptions: Assumptions;
  options: OptionResult[];
  decision_table: {
    option_id: string;
    cost_usd: number;
    ready_at_days: number;
    verified_coverage_pct: number;
    conditional_coverage_pct: number;
    status: PlannerStatus;
  }[];
  note: string;
}

const norm = (s: string) => String(s ?? "").trim().toLowerCase();

function skillLevel(person: { skills: PersonSkill[] }, skill: string): number | null {
  const hit = (person.skills ?? []).find((s) => norm(s.name) === norm(skill));
  return hit && hit.proficiency > 0 ? hit.proficiency : null;
}

/** Candidates: only active/invited, not rejected/expired/stale, with enough
 *  known skill data to assess (item 16). */
function usableCandidates(candidates: Candidate[], assumptions: Assumptions): Candidate[] {
  const now = Date.now();
  const STALE = assumptions.candidate_stale_days * 86400000;
  return (candidates ?? []).filter((c) => {
    if (!["active", "invited"].includes(c.status)) return false;
    if (c.applied_at && now - new Date(c.applied_at).getTime() > STALE) return false;
    if ((c.skills ?? []).length === 0 && c.match_score == null) return false;
    return true;
  });
}

function latestFinish(stages: Stage[]): number {
  // Sequential stages sum; parallel stages contribute their max within a
  // group. Model: stages in order; a stage with parallel:true runs alongside
  // the previous sequential stage and adds its max.
  let seq = 0;
  let runningMax = 0;
  for (const s of stages) {
    if (s.parallel) {
      runningMax = Math.max(runningMax, s.duration_days);
    } else {
      seq += s.duration_days + runningMax;
      runningMax = 0;
    }
  }
  return seq + runningMax;
}

function coverageRow(
  req: RequiredSkill,
  coverage: CoverageKind,
  current: number | null,
  projected: number | null,
  source: string
): SkillCoverageRow {
  const effective = coverage === "verified" ? (projected ?? current ?? 0) : coverage === "conditional" ? (projected ?? 0) : 0;
  return {
    skill: req.skill,
    min_proficiency: req.min_proficiency,
    mandatory: req.mandatory,
    coverage,
    current_proficiency: current,
    projected_proficiency: projected,
    source,
    mandatory_satisfied: !req.mandatory || effective >= req.min_proficiency,
  };
}

function planSummary(input: ScenarioInput, a: Assumptions, population: Person[], candidates: Candidate[]): PlanResult {
  const usable = usableCandidates(candidates, a);
  const skills = input.required_skills;

  // Shared coverage helper across options.
  const coverageFor = (person: Person | null, trained: Set<string>): SkillCoverageRow[] =>
    skills.map((req) => {
      const cur = person ? skillLevel(person, req.skill) : null;
      if (cur !== null && cur >= req.min_proficiency) {
        return coverageRow(req, "verified", cur, cur, `verified ${cur}/${req.min_proficiency}`);
      }
      if (person && trained.has(norm(req.skill))) {
        return coverageRow(req, "conditional", cur, req.min_proficiency, `training projection to ${req.min_proficiency} — pending verification`);
      }
      if (person) {
        return coverageRow(req, "gap", cur, null, `below required bar (${cur ?? "none"}/${req.min_proficiency})`);
      }
      return coverageRow(req, "absent", null, null, "no source identified");
    });

  const summarize = (rows: SkillCoverageRow[]) => {
    const verified = rows.filter((r) => r.coverage === "verified").length;
    const conditional = rows.filter((r) => r.coverage === "conditional").length;
    const mandatoryMissing = rows.filter((r) => r.mandatory && !r.mandatory_satisfied).map((r) => r.skill);
    return {
      verified_coverage_pct: Math.round((verified / Math.max(1, rows.length)) * 100),
      conditional_coverage_pct: Math.round(((verified + conditional) / Math.max(1, rows.length)) * 100),
      mandatory_satisfied: mandatoryMissing.length === 0,
      mandatory_missing: mandatoryMissing,
    };
  };

  const options: OptionResult[] = [];

  // --- HIRE ------------------------------------------------------------------
  const hireSubject = usable
    .map((c) => ({
      c,
      matched: skills.filter((r) => {
        const lvl = skillLevel(c, r.skill);
        return lvl !== null && lvl >= r.min_proficiency;
      }).length,
      mandatoryOk: skills.filter((r) => r.mandatory).every((r) => {
        const lvl = skillLevel(c, r.skill);
        return lvl !== null && lvl >= r.min_proficiency;
      }),
    }))
    .filter((x) => x.matched > 0 && x.mandatoryOk)
    .sort((x, y) => y.matched - x.matched)[0];

  if (hireSubject) {
    const rows = coverageFor(hireSubject.c, new Set());
    const s = summarize(rows);
    const ready = latestFinish([{ name: `Hire "${hireSubject.c.name}"`, kind: "hire", duration_days: a.hire_lead_days, parallel: false }]);
    const meets = ready <= input.deadline_days;
    const status: PlannerStatus = meets ? "conditional" : "infeasible";
    options.push({
      id: "hire",
      label: "Hire externally",
      status,
      status_reason: meets
        ? "Feasible only if the external hire completes on time — external lead time is a stated condition, not a certainty. 54% (or any) aggregate match is never role-ready on its own; readiness is gated on each mandatory skill."
        : `The hire track needs ${ready} days (lead time ${a.hire_lead_days}d), beyond the ${input.deadline_days}-day deadline. It is NOT clamped to the deadline — it is infeasible for this window.`,
      skill_coverage: rows,
      verified_coverage_pct: s.verified_coverage_pct,
      conditional_coverage_pct: s.conditional_coverage_pct,
      mandatory_satisfied: s.mandatory_satisfied,
      mandatory_missing: s.mandatory_missing,
      timeline: [{ name: "Hire + onboarding", kind: "hire", duration_days: a.hire_lead_days, parallel: false }],
      ready_at_days: ready,
      meets_deadline: meets,
      cost_usd: a.hire_cost_usd,
      budget_satisfied: a.hire_cost_usd <= input.budget_usd,
      dependency_risk: "high",
      constraints_satisfied: [
        "Mandatory skills covered by the candidate's claims at the required bar",
        `Hire lead time ${a.hire_lead_days}d modeled as a single external stage`,
      ],
      constraints_violated: meets ? [] : [`Hire ready at day ${ready} exceeds the ${input.deadline_days}-day deadline`],
      rationale: `Hire can cover all mandatory skills via ${hireSubject.c.name}, but depends on a ${a.hire_lead_days}-day external lead time. It fails whenever the deadline is shorter than that, which is exactly why ${meets ? "it remains conditional, not ready" : "it is infeasible here"}.`,
      subject: hireSubject.c.name,
    });
  } else {
    options.push({
      id: "hire",
      label: "Hire externally",
      status: usable.length === 0 ? "insufficient_data" : "infeasible",
      status_reason: usable.length === 0
        ? "No usable candidate records exist in the pipeline (rejected/expired/stale records were excluded by rule) — insufficient data to assess a hire."
        : "No candidate in the usable pipeline satisfies every mandatory skill at the required bar — a hire cannot be called role-ready.",
      skill_coverage: skills.map((r) => coverageRow(r, "absent", null, null, "no candidate satisfies this requirement")),
      verified_coverage_pct: 0,
      conditional_coverage_pct: 0,
      mandatory_satisfied: false,
      mandatory_missing: skills.filter((r) => r.mandatory).map((r) => r.skill),
      timeline: [{ name: "Hire + onboarding", kind: "hire", duration_days: a.hire_lead_days, parallel: false }],
      ready_at_days: a.hire_lead_days,
      meets_deadline: a.hire_lead_days <= input.deadline_days,
      cost_usd: a.hire_cost_usd,
      budget_satisfied: a.hire_cost_usd <= input.budget_usd,
      dependency_risk: "high",
      constraints_satisfied: [],
      constraints_violated: ["No suitable candidate covers every mandatory skill"],
      rationale: "External hire cannot be assessed as role-ready without a candidate who meets every mandatory skill. A partial or low match does not make the role ready.",
    });
  }

  // --- INTERNAL MOVE -----------------------------------------------------------
  const moveCandidates = population
    .map((p) => ({ p, matched: skills.filter((r) => (skillLevel(p, r.skill) ?? 0) >= r.min_proficiency).length }))
    .sort((x, y) => y.matched - x.matched);
  const bestMove = moveCandidates.find((x) =>
    skills.filter((r) => r.mandatory).every((r) => (skillLevel(x.p, r.skill) ?? 0) >= r.min_proficiency)
  ) ?? moveCandidates[0];

  if (bestMove && bestMove.matched > 0) {
    const rows = coverageFor(bestMove.p, new Set());
    const s = summarize(rows);
    const unavailable = Boolean(bestMove.p.current_assignment);
    const stages: Stage[] = [
      { name: "Source-manager approval", kind: "approval", duration_days: a.manager_approval_days, parallel: false },
      { name: "Handover + transition", kind: "handover", duration_days: a.move_transition_days, parallel: false },
    ];
    const ready = latestFinish(stages);
    const meets = ready <= input.deadline_days && !unavailable;
    const status: PlannerStatus = !s.mandatory_satisfied ? "infeasible" : unavailable ? "infeasible" : meets ? "feasible" : "infeasible";
    options.push({
      id: "move",
      label: "Internal move",
      status,
      status_reason: s.mandatory_satisfied
        ? unavailable
          ? `${bestMove.p.name} is currently assigned to "${bestMove.p.current_assignment}" — an internal move requires availability; until a backfill is approved the move is infeasible.`
          : meets
            ? `Move is ready in ${ready} days (approval ${a.manager_approval_days}d + handover ${a.move_transition_days}d), inside the ${input.deadline_days}-day window. Feasible.`
            : `Move needs ${ready} days, beyond the ${input.deadline_days}-day window — not clamped, therefore infeasible for this deadline.`
        : `Move fails the mandatory-skill gate: ${s.mandatory_missing.join(", ")} are not verified at the required bar.`,
      skill_coverage: rows,
      verified_coverage_pct: s.verified_coverage_pct,
      conditional_coverage_pct: s.conditional_coverage_pct,
      mandatory_satisfied: s.mandatory_satisfied,
      mandatory_missing: s.mandatory_missing,
      timeline: stages,
      ready_at_days: ready,
      meets_deadline: meets,
      cost_usd: a.move_cost_usd,
      budget_satisfied: a.move_cost_usd <= input.budget_usd,
      dependency_risk: unavailable ? "high" : "medium",
      constraints_satisfied: [
        s.mandatory_satisfied ? "All mandatory skills verified on the candidate" : "—",
        "Availability and source-manager approval are explicit stages",
        "Handover/backfill impact modeled as a 14-day transition",
      ].filter((c) => c !== "—"),
      constraints_violated: [
        ...(unavailable ? [`Currently assigned to "${bestMove.p.current_assignment}" — needs a backfill decision`] : []),
        ...(meets ? [] : [`Move ready at day ${ready} exceeds the ${input.deadline_days}-day deadline`]),
      ],
      rationale: `Move uses ${bestMove.p.name}'s verified skills (${s.verified_coverage_pct}% verified coverage). It satisfies the mandatory-skill gate${unavailable ? " but is blocked by a current assignment, so alternatives must be considered" : meets ? " and fits the window" : " but not the window, so it fails where hire/upskill timing or availability differ"}.`,
      subject: bestMove.p.name,
    });
  } else {
    options.push({
      id: "move",
      label: "Internal move",
      status: population.length === 0 ? "insufficient_data" : "infeasible",
      status_reason: population.length === 0
        ? "No authorized internal population is available in this scope — insufficient data to assess a move."
        : "No internal person in scope covers any required skill at the minimum bar — an internal move cannot be role-ready.",
      skill_coverage: skills.map((r) => coverageRow(r, "absent", null, null, "no internal candidate covers this skill")),
      verified_coverage_pct: 0,
      conditional_coverage_pct: 0,
      mandatory_satisfied: false,
      mandatory_missing: skills.filter((r) => r.mandatory).map((r) => r.skill),
      timeline: [
        { name: "Source-manager approval", kind: "approval", duration_days: a.manager_approval_days, parallel: false },
        { name: "Handover + transition", kind: "handover", duration_days: a.move_transition_days, parallel: false },
      ],
      ready_at_days: a.manager_approval_days + a.move_transition_days,
      meets_deadline: a.manager_approval_days + a.move_transition_days <= input.deadline_days,
      cost_usd: a.move_cost_usd,
      budget_satisfied: a.move_cost_usd <= input.budget_usd,
      dependency_risk: "medium",
      constraints_satisfied: [],
      constraints_violated: ["No internal person covers the required skills at the bar"],
      rationale: "Without an internal person who already covers the required skills, an internal move cannot satisfy the mandatory-skill gate.",
    });
  }

  // --- UPSKILL ----------------------------------------------------------------
  const bestUpskill = [...moveCandidates].sort((x, y) => y.matched - x.matched)[0];
  if (bestUpskill && bestUpskill.matched > 0) {
    const toTrain = new Set(skills.filter((r) => (skillLevel(bestUpskill.p, r.skill) ?? 0) < r.min_proficiency).map((r) => norm(r.skill)));
    const rows = coverageFor(bestUpskill.p, toTrain);
    const s = summarize(rows);
    const trainCount = skills.filter((r) => toTrain.has(norm(r.skill))).length;
    const stages: Stage[] = [
      ...skills.filter((r) => toTrain.has(norm(r.skill))).map((r) => ({ name: `Train ${r.skill}`, kind: "training" as const, duration_days: a.training_days_per_skill, parallel: false })),
      { name: "Evidence verification", kind: "verification", duration_days: a.verification_days, parallel: false },
    ];
    const ready = latestFinish(stages);
    const meets = ready <= input.deadline_days;
    // Training is a CONDITIONAL projection until verification succeeds (item 13).
    const status: PlannerStatus = trainCount === 0 ? "feasible" : meets ? "conditional" : "infeasible";
    const cost = a.training_cost_usd_per_skill * trainCount;
    options.push({
      id: "upskill",
      label: "Upskill internally",
      status,
      status_reason: trainCount === 0
        ? `${bestUpskill.p.name} already covers every required skill — no training needed; this collapses to a move (see Move).`
        : meets
          ? `Upskill projects ${bestUpskill.p.name} to the required bars for ${trainCount} skill(s), then requires evidence verification. Coverage is CONDITIONAL until verification succeeds — training does not create verified capability by itself.`
          : `Training (${trainCount} skill(s) × ${a.training_days_per_skill}d) + verification (${a.verification_days}d) needs ${ready} days, beyond the ${input.deadline_days}-day window — not clamped, therefore infeasible for this deadline.`,
      skill_coverage: rows,
      verified_coverage_pct: s.verified_coverage_pct,
      conditional_coverage_pct: s.conditional_coverage_pct,
      mandatory_satisfied: s.mandatory_satisfied,
      mandatory_missing: s.mandatory_missing,
      timeline: stages,
      ready_at_days: ready,
      meets_deadline: meets,
      cost_usd: cost,
      budget_satisfied: cost <= input.budget_usd,
      dependency_risk: "medium",
      constraints_satisfied: [
        "Mandatory skills reach the bar (verified or conditional-on-verification)",
        "Training staged sequentially with explicit verification",
      ],
      constraints_violated: meets ? [] : [`Upskill ready at day ${ready} exceeds the ${input.deadline_days}-day deadline`],
      rationale: `Upskill builds on ${bestUpskill.p.name}'s ${s.verified_coverage_pct}% verified coverage and projects the missing skills as CONDITIONAL. It cannot be called ready before verification — which is why it fails when the deadline is shorter than training+verification.`,
      subject: bestUpskill.p.name,
    });
  } else {
    options.push({
      id: "upskill",
      label: "Upskill internally",
      status: population.length === 0 ? "insufficient_data" : "infeasible",
      status_reason: "No internal person provides a verified starting point — upskilling from nothing cannot be projected reliably.",
      skill_coverage: skills.map((r) => coverageRow(r, "absent", null, null, "no internal starting point")),
      verified_coverage_pct: 0,
      conditional_coverage_pct: 0,
      mandatory_satisfied: false,
      mandatory_missing: skills.filter((r) => r.mandatory).map((r) => r.skill),
      timeline: [],
      ready_at_days: 0,
      meets_deadline: false,
      cost_usd: 0,
      budget_satisfied: true,
      dependency_risk: "medium",
      constraints_satisfied: [],
      constraints_violated: ["No verified internal starting point"],
      rationale: "Upskill requires a verified base to project from; with none available it is infeasible.",
    });
  }

  // --- HYBRID (hire + upskill) ------------------------------------------------
  const hireOpt = options.find((o) => o.id === "hire");
  const upskillOpt = options.find((o) => o.id === "upskill");
  if (hireOpt && upskillOpt && hireOpt.subject && upskillOpt.subject) {
    // BOTH tracks must finish; the hybrid is ready when the LATEST track is
    // done (item 18) — never clamped, never min().
    const hireReady = hireOpt.ready_at_days;
    const upReady = upskillOpt.ready_at_days;
    const ready = Math.max(hireReady, upReady);
    const meets = ready <= input.deadline_days;
    const totalCost = hireOpt.cost_usd + upskillOpt.cost_usd;
    const rows = skills.map((r) => {
      const h = hireOpt.skill_coverage.find((x) => norm(x.skill) === norm(r.skill));
      const u = upskillOpt.skill_coverage.find((x) => norm(x.skill) === norm(r.skill));
      const viaHire = h && (h.coverage === "verified" || h.coverage === "conditional");
      const viaUpskill = u && u.coverage !== "absent";
      const best = [h, u].find((x) => x && (x.coverage === "verified" || x.coverage === "conditional"));
      const cur = Math.max(h?.current_proficiency ?? 0, u?.current_proficiency ?? 0) || null;
      return coverageRow(
        r,
        best ? best.coverage : "gap",
        cur,
        r.min_proficiency,
        best ? `covered by ${best.source}` : "no hybrid path"
      );
    });
    const s = summarize(rows);
    const phaseNote = hireReady > upReady
      ? `Upskill track is ready at day ${upReady}; the hire completes at day ${hireReady}. The team is NOT fully ready until day ${ready} — phased availability: ${upskillOpt.subject} at day ${upReady}, full team at day ${ready}.`
      : upReady > hireReady
        ? `Hire track is ready at day ${hireReady}; upskill completes at day ${upReady}. Phased availability: ${hireOpt.subject} at day ${hireReady}, full team at day ${ready}.`
        : `Both tracks finish at day ${ready}.`;
    const status: PlannerStatus = meets ? "conditional" : "infeasible";
    options.push({
      id: "hybrid",
      label: "Hybrid (hire + upskill)",
      status,
      status_reason: meets
        ? `${phaseNote} Readiness is conditional on both tracks executing (hire completing + training verifying).`
        : `${phaseNote} The latest required finish (day ${ready}) exceeds the ${input.deadline_days}-day window, so the hybrid is NOT ready by the deadline — never clamped.`,
      skill_coverage: rows,
      verified_coverage_pct: s.verified_coverage_pct,
      conditional_coverage_pct: s.conditional_coverage_pct,
      mandatory_satisfied: s.mandatory_satisfied,
      mandatory_missing: s.mandatory_missing,
      timeline: [
        { name: "Hire track", kind: "hire", duration_days: hireReady, parallel: true },
        { name: "Upskill track", kind: "training", duration_days: upReady, parallel: true },
      ],
      ready_at_days: ready,
      meets_deadline: meets,
      cost_usd: totalCost,
      budget_satisfied: totalCost <= input.budget_usd,
      dependency_risk: "high",
      constraints_satisfied: [
        "Both tracks' mandatory coverage combined",
        "Phased availability described explicitly (not 'entire hybrid ready')",
      ],
      constraints_violated: meets ? [] : [`Latest finish day ${ready} > deadline ${input.deadline_days}`],
      rationale: `Hybrid combines hire (ready day ${hireReady}) and upskill (ready day ${upReady}); it is ready only at the latest finish (day ${ready}) because both tracks must finish (item 18). ${meets ? "It satisfies the window but stays conditional on execution." : "It fails the window because the latest finish cannot be clamped."}`,
      subject: `${hireOpt.subject} + ${upskillOpt.subject}`,
    });
  }

  const decision_table = options.map((o) => ({
    option_id: o.id,
    cost_usd: o.cost_usd,
    ready_at_days: o.ready_at_days,
    verified_coverage_pct: o.verified_coverage_pct,
    conditional_coverage_pct: o.conditional_coverage_pct,
    status: o.status,
  }));

  return {
    scenario: input,
    assumptions: a,
    options,
    decision_table,
    note: "Deterministic constrained planner: skill-by-skill coverage, mandatory-skill gates, sequential/parallel timing with the actual latest finish (never clamped), and a status vocabulary of feasible / conditional / infeasible / insufficient_data. Cost and duration are explicit assumptions; the model may explain but never invent the numbers.",
  };
}

/** Public entry: plan against an internal population + candidate pipeline. */
export function planStaffing(
  input: ScenarioInput,
  population: Person[],
  candidates: Candidate[],
  assumptions: Assumptions = DEFAULT_ASSUMPTIONS
): PlanResult {
  return planSummary(input, assumptions, population, candidates);
}


// ---------------------------------------------------------------------------
// WorkSense Qwen gateway client — server-managed config, strict output
// validation, one controlled repair attempt, sanitized telemetry.
// Called ONLY from backend functions. The tunnel URL / credentials never
// ship to the browser.
// ---------------------------------------------------------------------------

function getEnv(name: string, fallback: string): string {
  try {
    const deno = (globalThis as { Deno?: { env?: { get?: (n: string) => string | undefined } } }).Deno;
    const fromDeno = deno?.env?.get?.(name);
    if (fromDeno !== undefined) return fromDeno;
  } catch {
    /* node test env */
  }
  try {
    return (typeof process !== "undefined" ? process.env?.[name] : undefined) ?? fallback;
  } catch {
    return fallback;
  }
}

function getEnvInt(name: string, fallback: number): number {
  const v = Number(getEnv(name, String(fallback)));
  return Number.isFinite(v) && v > 0 ? Math.floor(v) : fallback;
}

// --- Server-managed settings (env with sane defaults) ----------------------
export const QWEN_BASE_URL = getEnv("QWEN_BASE_URL", "https://evolve-eternity-epidural.ngrok-free.dev/v1").replace(/\/+$/, "");
export const QWEN_MODEL = getEnv("QWEN_MODEL", "qwen3:4b-instruct-2507-q4_K_M");
export const QWEN_API_KEY = getEnv("QWEN_API_KEY", "local");
/** Optional real gateway auth (e.g. "Basic dXNlcjpwYXNz" or "Bearer x") for a protected tunnel. */
export const QWEN_GATEWAY_AUTH = getEnv("QWEN_GATEWAY_AUTH", "");
export const QWEN_TIMEOUT_MS = getEnvInt("QWEN_TIMEOUT_MS", 100000);
export const QWEN_MAX_INPUT_CHARS = getEnvInt("QWEN_MAX_INPUT_CHARS", 8000);
export const QWEN_MAX_TOKENS = getEnvInt("QWEN_MAX_TOKENS", 1600);

export type QwenErrorCode = "MODEL_UNAVAILABLE" | "MODEL_OUTPUT_INVALID" | "VALIDATION_ERROR" | "INPUT_TOO_LARGE";

export class QwenError extends Error {
  constructor(public code: QwenErrorCode, message: string) {
    super(message);
    this.name = "QwenError";
  }
}

// ---------------------------------------------------------------------------
// Untrusted-content handling (resume intake)
// ---------------------------------------------------------------------------

const INSTRUCTION_PATTERNS: RegExp[] = [
  /\bignore\s+(?:(?:all|any|the|your|previous|prior|above|system|developer)\s+)*(?:instructions?|prompts?|rules?|context|messages?|output)\b/gi,
  /\bdisregard\s+(?:(?:all|any|the|your|previous|prior|above|system|developer)\s+)*(?:instructions?|prompts?|rules?|context)\b/gi,
  /\bdo\s+not\s+(?:follow|obey|listen\s+to)\b/gi,
  /\byou\s+are\s+now\b/gi,
  /\bsystem\s+prompt\b/gi,
  /\bdeveloper\s+message\b/gi,
  /\bjailbreak\b/gi,
  /\boverride\s+(?:(?:your|the|system|developer)\s+)*(?:instructions?|rules?|prompt)\b/gi,
  /\bpretend\s+(?:to\s+|that\s+|you\s+)/gi,
  /\bsay\s+you\s+(?:are|have|would|can)\b/gi,
  /\bgive\s+(?:me\s+)?(?:a\s+)?100\s*%?\s*(?:match|fit|score)\b/gi,
  /\balways\s+(?:ignore|follow|obey)\b/gi,
  /\breveal\s+(?:your|the)\s+(?:system|instructions?|prompt)\b/gi,
];

/** Neutralize instruction-like phrases in untrusted resume text. */
export function sanitizeUntrusted(text: string): string {
  let out = String(text ?? "");
  for (const re of INSTRUCTION_PATTERNS) out = out.replace(re, "[redacted]");
  return out.trim();
}

/** Explicit delimiter marking untrusted content for the model. */
export function wrapUntrusted(text: string): string {
  return `<untrusted_input>\n${text}\n</untrusted_input>`;
}

// ---------------------------------------------------------------------------
// Strict JSON extraction — never salvage arbitrary brace substrings blindly.
// ---------------------------------------------------------------------------

export function isHtmlInterstitial(content: string): boolean {
  const head = String(content ?? "").slice(0, 400).trim().toLowerCase();
  return /^<!doctype|^<html|ngrok|502 bad gateway|504 gateway time-out|cloudflare/.test(head);
}

export function extractJsonStrict(content: string): unknown {
  const trimmed = String(content ?? "").trim();
  if (!trimmed) throw new QwenError("MODEL_OUTPUT_INVALID", "qwen: empty completion");
  if (isHtmlInterstitial(trimmed)) {
    throw new QwenError("MODEL_UNAVAILABLE", "qwen: gateway returned an HTML/interstitial response (infrastructure error, not model output).");
  }
  // 1) strict full parse
  try {
    return JSON.parse(trimmed);
  } catch {
    /* fall through */
  }
  // 2) strip markdown fences
  const fenced = trimmed.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "").trim();
  try {
    return JSON.parse(fenced);
  } catch {
    /* fall through */
  }
  // 3) balanced object extraction (only if the remainder is clearly a JSON object)
  const start = fenced.indexOf("{");
  const end = fenced.lastIndexOf("}");
  if (start !== -1 && end > start) {
    const candidate = fenced.slice(start, end + 1);
    // Reject if non-whitespace noise precedes the object or trails it.
    const prefixNoise = fenced.slice(0, start).trim();
    const suffixNoise = fenced.slice(end + 1).trim();
    if (prefixNoise.length <= 40 && suffixNoise.length <= 40) {
      try {
        return JSON.parse(candidate);
      } catch {
        throw new QwenError("MODEL_OUTPUT_INVALID", "qwen: unbalanced JSON in response.");
      }
    }
  }
  throw new QwenError("MODEL_OUTPUT_INVALID", `qwen: no valid JSON object in response (${trimmed.slice(0, 160)}…)`);
}

// ---------------------------------------------------------------------------
// Sanitized telemetry — never log raw prompts.
// ---------------------------------------------------------------------------

function logMetric(entry: Record<string, string | number>) {
  console.log(`[qwen] ${Object.entries(entry).map(([k, v]) => `${k}=${v}`).join(" ")}`);
}

// ---------------------------------------------------------------------------
// OpenAI-compatible chat call
// ---------------------------------------------------------------------------

export async function callQwen(params: {
  system: string;
  user: string;
  json?: boolean;
  maxTokens?: number;
  temperature?: number;
  task?: string;
  timeoutMs?: number;
}): Promise<unknown> {
  const task = params.task ?? "generic";
  const started = Date.now();
  const inputChars = String(params.user ?? "").length;

  if (inputChars > QWEN_MAX_INPUT_CHARS) {
    logMetric({ task, status: "rejected", reason: "input_too_large", input_chars: inputChars });
    throw new QwenError("INPUT_TOO_LARGE", `Input exceeds the ${QWEN_MAX_INPUT_CHARS} character limit.`);
  }

  const messages: { role: string; content: string }[] = [
    { role: "system", content: params.system },
    { role: "user", content: params.user },
  ];
  const body: Record<string, unknown> = {
    model: QWEN_MODEL,
    messages,
    temperature: params.temperature ?? 0.2,
    max_tokens: params.maxTokens ?? QWEN_MAX_TOKENS,
    stream: false,
  };
  if (params.json) body.response_format = { type: "json_object" };

  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Authorization: `Bearer ${QWEN_API_KEY}`,
  };
  if (QWEN_GATEWAY_AUTH) headers["Authorization"] = QWEN_GATEWAY_AUTH;

  const attempt = async (repairHint: boolean): Promise<unknown> => {
    const controller = new AbortController();
    const timeoutMs = params.timeoutMs ?? QWEN_TIMEOUT_MS;
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    let res: Response;
    try {
      res = await fetch(`${QWEN_BASE_URL}/chat/completions`, {
        method: "POST",
        headers,
        body: JSON.stringify(repairHint ? { ...body, messages: [...messages, { role: "user", content: "IMPORTANT: respond with ONLY valid JSON and nothing else. No markdown fences, no prose." }] } : body),
        signal: controller.signal,
      });
    } catch (err) {
      const timedOut = err instanceof Error && err.name === "AbortError";
      throw new QwenError("MODEL_UNAVAILABLE", timedOut ? `qwen: request timed out after ${timeoutMs}ms` : `qwen: network error (is the endpoint reachable?): ${err instanceof Error ? err.message : String(err)}`);
    } finally {
      clearTimeout(timer);
    }

    if (!res.ok) {
      const text = await res.text();
      if (isHtmlInterstitial(text)) {
        throw new QwenError("MODEL_UNAVAILABLE", "qwen: gateway returned an HTML/interstitial response (infrastructure error).");
      }
      throw new QwenError("MODEL_UNAVAILABLE", `qwen: HTTP ${res.status}: ${text.slice(0, 300)}`);
    }

    const data = await res.json();
    const content = data?.choices?.[0]?.message?.content;
    if (typeof content !== "string" || content.length === 0) {
      throw new QwenError("MODEL_OUTPUT_INVALID", "qwen: empty completion");
    }
    if (!params.json) return content;

    const usage = data?.usage;
    const latency = Date.now() - started;
    try {
      const parsed = extractJsonStrict(content);
      logMetric({
        task, status: "ok", latency_ms: latency,
        model: QWEN_MODEL, out_chars: content.length,
        tokens_in: usage?.prompt_tokens ?? 0, tokens_out: usage?.completion_tokens ?? 0,
        input_chars: inputChars,
      });
      return parsed;
    } catch (err) {
      if (err instanceof QwenError) {
        if (err.code === "MODEL_OUTPUT_INVALID" && !repairHint) {
          // Exactly one controlled repair attempt.
          logMetric({ task, status: "repair", latency_ms: latency, reason: err.message.slice(0, 80) });
          return attempt(true);
        }
        logMetric({ task, status: "failed", latency_ms: latency, code: err.code });
        throw err;
      }
      throw err;
    }
  };

  return attempt(false);
}


// Batch 10: pure decision rules for the staffing-proposal human-review loop.
//
// A proposal binds the selected option + the scenario version it was computed
// at. A human reviewer either approves it (which may dispatch an owned
// follow-up task when the option resolves to an existing employee) or declines
// it — either way the decision is a durable record (status, reviewer, note,
// timestamp) that the submitter sees. This module only decides WHAT to persist;
// all DB lookups/writes happen in the calling function, so the rules are
// trivially unit-testable and cannot accidentally grant access.

export const PROPOSAL_DECISIONS = ["approved", "declined"] as const;
export type ProposalDecision = (typeof PROPOSAL_DECISIONS)[number];

export const PROPOSAL_REVIEWER_ROLES = ["hr_executive", "hr_partner"] as const;
export type ProposalReviewerRole = (typeof PROPOSAL_REVIEWER_ROLES)[number];

/** Follow-up task dispatched when an approved proposal resolves to an employee. */
export const PROPOSAL_FOLLOW_UP_TASK = {
  task_code: "staffing_transition",
  title: (optionLabel: string) => `Execute approved staffing decision — ${optionLabel}`,
  due_in_days: 14,
  required_evidence: ["work_reference"],
  outcome_measure: { metric: "transition_completed", target: true },
} as const;

export function isProposalDecision(value: unknown): value is ProposalDecision {
  return typeof value === "string" && (PROPOSAL_DECISIONS as readonly string[]).includes(value);
}

export interface DecisionInput {
  proposal: { status: string; option_label: string | null; option_snapshot: unknown };
  decision: ProposalDecision;
  reviewNote: string | null;
  reviewerId: string;
  now: string;
}

export interface DecisionPlan {
  /** The persisted update for the proposal row (version-guarded by the caller). */
  update: { status: ProposalDecision; review_note: string; reviewed_by: string; reviewed_at: string };
  /** Option subject name when approval should dispatch an owned follow-up task. */
  subjectName: string | null;
}

export function planProposalDecision(input: DecisionInput): DecisionPlan {
  const snapshot = (input.proposal.option_snapshot ?? {}) as { subject?: unknown };
  const subject = typeof snapshot.subject === "string" && snapshot.subject.trim() ? snapshot.subject.trim() : null;
  return {
    update: {
      status: input.decision,
      review_note:
        input.reviewNote ??
        (input.decision === "approved"
          ? "Approved — proceed with the staffing decision."
          : "Declined — not approved at this time."),
      reviewed_by: input.reviewerId,
      reviewed_at: input.now,
    },
    subjectName: input.decision === "approved" ? subject : null,
  };
}

export interface FollowUpTaskInput {
  orgId: string;
  ownerTwinId: string;
  optionLabel: string;
  proposalId: string;
  now: string;
}

/**
 * Row for an employee-owned action task that surfaces in the subject's My work
 * feed. `created_by_request_id` is the idempotency key (staffing-proposal:<id>)
 * so duplicate review calls can never double-dispatch.
 */
export function buildFollowUpTaskRow(input: FollowUpTaskInput) {
  return {
    org_id: input.orgId,
    owner_twin_id: input.ownerTwinId,
    owner_role: "employee",
    task_code: PROPOSAL_FOLLOW_UP_TASK.task_code,
    title: PROPOSAL_FOLLOW_UP_TASK.title(input.optionLabel),
    status: "open",
    due_at: new Date(new Date(input.now).getTime() + PROPOSAL_FOLLOW_UP_TASK.due_in_days * 86400000).toISOString(),
    instructions: `Approved staffing decision: ${input.optionLabel}. Coordinate the transition with the responsible HR partner, complete the required steps, and attach evidence when done.`,
    required_evidence: [...PROPOSAL_FOLLOW_UP_TASK.required_evidence],
    outcome_measure: { ...PROPOSAL_FOLLOW_UP_TASK.outcome_measure },
    outcome: {},
    created_by_request_id: `staffing-proposal:${input.proposalId}`,
  };
}


import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.0";




const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};
const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

async function isTeamMember(supabase, rootTwinId: string, checkTwinId: string): Promise<boolean> {
  const { data } = await supabase.from("digital_twins").select("id, manager_id");
  const children = new Map<string, string[]>();
  for (const t of data ?? []) if (t.manager_id) children.set(t.manager_id, [...(children.get(t.manager_id) ?? []), t.id]);
  const seen = new Set<string>();
  const stack = [rootTwinId];
  while (stack.length > 0) {
    const cur = stack.pop()!;
    if (seen.has(cur)) continue;
    seen.add(cur);
    for (const c of children.get(cur) ?? []) stack.push(c);
  }
  return seen.has(checkTwinId);
}

async function teamTwinIds(supabase, rootTwinId: string): Promise<Set<string>> {
  const { data } = await supabase.from("digital_twins").select("id, manager_id");
  const children = new Map<string, string[]>();
  for (const t of data ?? []) if (t.manager_id) children.set(t.manager_id, [...(children.get(t.manager_id) ?? []), t.id]);
  const seen = new Set<string>();
  const stack = [rootTwinId];
  while (stack.length > 0) {
    const cur = stack.pop()!;
    if (seen.has(cur)) continue;
    seen.add(cur);
    for (const c of children.get(cur) ?? []) stack.push(c);
  }
  return seen;
}

const NL = String.fromCharCode(10);

// Deterministic, stable fingerprint of a scenario's input snapshot so a
// proposal binds the exact input version it was generated from.
function stableHash(s: string): string {
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
  return h.toString(36);
}
function scenarioVersion(input: unknown, assumptions: unknown): string {
  const v = (assumptions as { version?: string })?.version ?? "?";
  return `v:${v}/input:${stableHash(JSON.stringify(input ?? {}))}`;
}

const EXPLAIN_SYSTEM = `You are the WorkSense staffing-planning narrator. You are given ONLY the validated numbers produced by the deterministic planner (options with status, cost, ready-day, verified/conditional coverage, mandatory gaps, deadline and budget).
Your job is to explain those numbers clearly. HARD RULES:
1. NEVER invent, recalculate, or change any number — restate exactly what the planner produced.
2. Do not claim an option is role-ready unless the planner says its status is feasible/conditional AND mandatory gaps are empty.
3. Never claim the 56-day hire track is ready at a 42-day deadline; restate the planner's ready-day and deadline as given.
4. Compare options on cost, time, verified coverage and risk using ONLY the provided values.
Respond with JSON only: {"explanation":"string"}`;

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  const supabase = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
  const authHeader = req.headers.get("Authorization") ?? "";
  const { data: userData } = await supabase.auth.getUser(authHeader.replace("Bearer ", ""));
  const uid = userData?.user?.id;
  if (!uid) return json({ error: "UNAUTHENTICATED" }, 401);

  const { data: caller } = await supabase
    .from("digital_twins")
    .select("id, role, email, org_id, name")
    .eq("auth_user_id", uid)
    .maybeSingle();
  if (!caller) return json({ error: "UNAUTHENTICATED" }, 401);
  if (!["hr_executive", "hr_partner", "manager"].includes(caller.role)) {
    return json({ error: "FORBIDDEN", message: "Staffing planner requires HR or Manager access." }, 403);
  }

  let body: Record<string, unknown> = {};
  try { body = await req.json(); } catch { /* empty */ }
  const action = String(body.action ?? "plan");

  // ---- list saved scenarios ---------------------------------------------------
  if (action === "list") {
    const { data, error } = await supabase
      .from("staffing_scenarios")
      .select("id, name, input_snapshot, assumptions, result, created_by, created_at")
      .eq("org_id", caller.org_id)
      .order("created_at", { ascending: false })
      .limit(10);
    if (error) return json({ error: "INTERNAL", message: error.message }, 500);
    const { data: props } = await supabase
      .from("staffing_proposals")
      .select("id, scenario_id, status, review_note, option_label, scenario_version, submitted_by, reviewed_by, reviewed_at, created_at")
      .eq("org_id", caller.org_id)
      .order("created_at", { ascending: false })
      .limit(20);
    // Server-side scope: managers only see proposals they (or their team)
    // submitted — never the org's full proposal list. HR sees all org proposals.
    let rows = props ?? [];
    if (caller.role === "manager") {
      const teamIds = await teamTwinIds(supabase, caller.id);
      rows = rows.filter((p) => p.submitted_by !== null && teamIds.has(p.submitted_by));
    }
    // Resolve twin ids to names once, so the review UI can show who submitted
    // and who decided without the frontend guessing.
    const personIds = [
      ...new Set(
        rows
          .flatMap((p) => [p.submitted_by, p.reviewed_by])
          .filter((id): id is string => typeof id === "string" && id.length > 0)
      ),
    ];
    const names = new Map<string, string>();
    if (personIds.length > 0) {
      const { data: people } = await supabase.from("digital_twins").select("id, name").in("id", personIds);
      for (const p of people ?? []) names.set(p.id, p.name);
    }
    return json({
      ok: true,
      scenarios: data ?? [],
      proposals: rows.map((p) => ({
        ...p,
        submitted_by_name: p.submitted_by ? (names.get(p.submitted_by) ?? null) : null,
        reviewed_by_name: p.reviewed_by ? (names.get(p.reviewed_by) ?? null) : null,
      })),
    });
  }

  // ---- propose a saved scenario for human review -------------------------------
  // Batch F: the proposal binds the SELECTED option and the scenario version it
  // was computed at (option_id + a full option snapshot + input/assumptions
  // fingerprint), so a review decision always points at the exact numbers seen.
  if (action === "propose") {
    const scenarioId = String(body.scenario_id ?? "").trim();
    const optionId = String(body.option_id ?? "").trim();
    if (!scenarioId) return json({ error: "VALIDATION_ERROR", message: "scenario_id is required." }, 400);
    if (!optionId) return json({ error: "VALIDATION_ERROR", message: "option_id is required — select an option in the comparison first." }, 400);
    const { data: scenario } = await supabase
      .from("staffing_scenarios")
      .select("id, name, input_snapshot, assumptions, result")
      .eq("org_id", caller.org_id)
      .eq("id", scenarioId)
      .maybeSingle();
    if (!scenario) return json({ error: "NOT_FOUND" }, 404);
    const result = (scenario.result ?? {}) as { options?: Record<string, unknown>[] };
    const option = (result.options ?? []).find((o) => o.id === optionId) ?? null;
    if (!option) {
      return json({ error: "VALIDATION_ERROR", message: "option_id must match an option computed for this scenario." }, 400);
    }
    const { data, error } = await supabase
      .from("staffing_proposals")
      .insert({
        org_id: caller.org_id,
        scenario_id: scenarioId,
        option_id: optionId,
        option_label: String(option.label ?? optionId),
        option_snapshot: option,
        scenario_version: scenarioVersion(scenario.input_snapshot, scenario.assumptions),
        status: "open",
        submitted_by: caller.id,
        review_note: "Submitted for human review from the staffing planner.",
      })
      .select("id, status, created_at, option_id, option_label, scenario_version")
      .single();
    if (error) return json({ error: "INTERNAL", message: error.message }, 500);
    return json({
      ok: true,
      proposal_id: data.id,
      status: data.status,
      message: "Proposal submitted for human review.",
      option_id: data.option_id,
      option_label: data.option_label,
      scenario_version: data.scenario_version,
    });
  }

  // ---- review a submitted proposal (human decision loop) ----------------------
  // Only HR reviewers decide. The decision is a durable record (status,
  // reviewer, note, timestamp) guarded by the open->decided transition; an
  // approval dispatches an employee-owned follow-up task when the option
  // resolves to an existing active employee.
  if (action === "review_proposal") {
    if (!["hr_executive", "hr_partner"].includes(caller.role)) {
      return json({ error: "FORBIDDEN", message: "Only HR reviewers can decide staffing proposals." }, 403);
    }
    const proposalId = String(body.proposal_id ?? "").trim();
    const decision = body.decision;
    if (!proposalId) return json({ error: "VALIDATION_ERROR", message: "proposal_id is required." }, 400);
    if (!isProposalDecision(decision)) {
      return json({ error: "VALIDATION_ERROR", message: "decision must be 'approved' or 'declined'." }, 400);
    }
    const reviewNote =
      typeof body.review_note === "string" && body.review_note.trim() ? body.review_note.trim().slice(0, 500) : null;

    const { data: proposal } = await supabase
      .from("staffing_proposals")
      .select("id, status, option_label, option_snapshot, scenario_version")
      .eq("org_id", caller.org_id)
      .eq("id", proposalId)
      .maybeSingle();
    if (!proposal) return json({ error: "NOT_FOUND", message: "No such proposal in this organization." }, 404);

    const plan = planProposalDecision({
      proposal: { status: proposal.status, option_label: proposal.option_label, option_snapshot: proposal.option_snapshot },
      decision,
      reviewNote,
      reviewerId: caller.id,
      now: new Date().toISOString(),
    });

    // Version guard: only an open proposal can be decided; a second review on
    // the same proposal is rejected (idempotency, never a silent overwrite).
    const { data: updated, error } = await supabase
      .from("staffing_proposals")
      .update(plan.update)
      .eq("org_id", caller.org_id)
      .eq("id", proposalId)
      .eq("status", "open")
      .select("id, status, option_label, scenario_version, review_note, submitted_by, reviewed_by, reviewed_at, created_at")
      .maybeSingle();
    if (error) return json({ error: "INTERNAL", message: error.message }, 500);
    if (!updated) return json({ error: "ALREADY_REVIEWED", message: "This proposal has already been reviewed." }, 409);

    // Approved + option names an active employee -> dispatch one owned task
    // (idempotency key = staffing-proposal:<id>, so no double dispatch).
    if (plan.subjectName) {
      const { data: subjectTwin } = await supabase
        .from("digital_twins")
        .select("id")
        .eq("org_id", caller.org_id)
        .eq("name", plan.subjectName)
        .eq("status", "active")
        .maybeSingle();
      if (subjectTwin) {
        const { error: taskErr } = await supabase.from("action_tasks").insert(
          buildFollowUpTaskRow({
            orgId: caller.org_id,
            ownerTwinId: subjectTwin.id,
            optionLabel: updated.option_label ?? proposal.option_label ?? "staffing decision",
            proposalId,
            now: plan.update.reviewed_at,
          })
        );
        if (taskErr) return json({ error: "INTERNAL", message: taskErr.message }, 500);
      }
    }

    return json({ ok: true, proposal: updated, message: `Proposal ${decision}.` });
  }

  // ---- explain a saved scenario (Qwen narrates ONLY the validated numbers) ------
  if (action === "explain") {
    const scenarioId = String(body.scenario_id ?? "").trim();
    if (!scenarioId) return json({ error: "VALIDATION_ERROR", message: "scenario_id is required." }, 400);
    const { data: scenario } = await supabase
      .from("staffing_scenarios")
      .select("name, result")
      .eq("org_id", caller.org_id)
      .eq("id", scenarioId)
      .maybeSingle();
    if (!scenario) return json({ error: "NOT_FOUND" }, 404);
    const result = (scenario.result ?? {}) as {
      options?: unknown[]; decision_table?: unknown[]; scenario?: { deadline_days?: number; budget_usd?: number };
    };
    const digest = {
      deadline_days: result.scenario?.deadline_days,
      budget_usd: result.scenario?.budget_usd,
      options: (result.options ?? []).map((o) => ({
        id: (o as { id?: string })?.id,
        status: (o as { status?: string })?.status,
        ready_at_days: (o as { ready_at_days?: number })?.ready_at_days,
        cost_usd: (o as { cost_usd?: number })?.cost_usd,
        verified_coverage_pct: (o as { verified_coverage_pct?: number })?.verified_coverage_pct,
        conditional_coverage_pct: (o as { conditional_coverage_pct?: number })?.conditional_coverage_pct,
        mandatory_missing: (o as { mandatory_missing?: string[] })?.mandatory_missing ?? [],
        meets_deadline: (o as { meets_deadline?: boolean })?.meets_deadline,
      })),
      decision_table: result.decision_table ?? [],
    };
    try {
      const parsed = (await callQwen({
        json: true,
        temperature: 0.2,
        maxTokens: 800,
        task: "staffing_explanation",
        system: EXPLAIN_SYSTEM,
        user: `Scenario "${scenario.name}".${NL}${NL}PLANNER OUTPUT (validated — restate exactly):${NL}${JSON.stringify(digest)}`,
      })) as { explanation?: string };
      return json({ ok: true, explanation: String(parsed.explanation ?? "") || "No explanation produced.", digest });
    } catch (err) {
      return json({ ok: true, explanation: null, digest, error: err instanceof QwenError ? err.code : "MODEL_UNAVAILABLE" });
    }
  }

  // ---- plan (default) ----------------------------------------------------------
  const scenarioInput: ScenarioInput = {
    name: String(body.name ?? `Scenario ${new Date().toLocaleDateString()}`).slice(0, 80),
    demand_title: String(body.demand_title ?? "Backend Engineer").slice(0, 120),
    department: body.department ? String(body.department).slice(0, 80) : undefined,
    required_skills: Array.isArray(body.required_skills) && body.required_skills.length > 0
      ? (body.required_skills as { skill: string; min_proficiency: number; mandatory?: boolean }[]).map((r) => ({
          skill: String(r.skill),
          min_proficiency: Math.max(1, Math.min(5, Number(r.min_proficiency) || 3)),
          mandatory: r.mandatory !== false,
        }))
      : [{ skill: "Go", min_proficiency: 3, mandatory: true }, { skill: "REST APIs", min_proficiency: 3, mandatory: true }],
    capacity_people: Math.max(1, Number(body.capacity_people) || 1),
    deadline_days: Math.max(1, Number(body.deadline_days) || 42),
    budget_usd: Math.max(0, Number(body.budget_usd) || 60000),
    geography: body.geography ? String(body.geography) : undefined,
    horizon_months: Math.max(1, Number(body.horizon_months) || 12),
    assumptions_version: String(body.assumptions_version ?? DEFAULT_ASSUMPTIONS.version),
  };

  // Authorized internal population: HR sees the org; managers see their team
  // (item 29 — a manager can never pull the wider org or candidate pipeline).
  const { data: twins } = await supabase
    .from("digital_twins")
    .select("id, name, role, department, manager_id, verified_skills, signals")
    .eq("org_id", caller.org_id)
    .eq("status", "active");
  const all = (twins ?? []) as {
    id: string; name: string; role: string; department: string | null; manager_id: string | null;
    verified_skills: { name: string; proficiency: number; verification_rigor?: string }[];
    signals?: { type?: string; value?: unknown }[];
  }[];
  let scopedPeople = all.filter((t) => ["employee", "manager"].includes(t.role));
  if (caller.role === "manager") {
    // Manager scope: the caller's reporting subtree only (item 29).
    const { data: allTwins2 } = await supabase.from("digital_twins").select("id, manager_id");
    const children = new Map<string, string[]>();
    for (const t of allTwins2 ?? []) if (t.manager_id) children.set(t.manager_id, [...(children.get(t.manager_id) ?? []), t.id]);
    const seen = new Set<string>();
    const stack = [caller.id];
    while (stack.length > 0) {
      const cur = stack.pop()!;
      if (seen.has(cur)) continue;
      seen.add(cur);
      for (const c of children.get(cur) ?? []) stack.push(c);
    }
    scopedPeople = scopedPeople.filter((p) => seen.has(p.id));
  }
  const population: Person[] = scopedPeople.map((t) => {
    const critical = (t.signals ?? []).find((s) => s.type === "critical_assignment");
    return {
      id: t.id,
      name: t.name,
      department: t.department,
      manager_id: t.manager_id,
      current_assignment: critical ? String(critical.value ?? "") : null,
      skills: (t.verified_skills ?? []).map((s) => ({
        name: s.name,
        proficiency: s.proficiency,
        verification_rigor: (s.verification_rigor ?? "low") as Person["skills"][number]["verification_rigor"],
      })),
    };
  });

  // Candidate pipeline: only visible to HR roles (managers stay scoped out).
  let candidates: Candidate[] = [];
  if (["hr_executive", "hr_partner"].includes(caller.role)) {
    const { data: reqs } = await supabase
      .from("job_requisitions")
      .select("id, title, applicants")
      .eq("org_id", caller.org_id)
      .eq("status", "open");
    const req = (reqs ?? []).find((r) => r.title.toLowerCase() === scenarioInput.demand_title.toLowerCase()) ?? (reqs ?? [])[0];
    const applicants = (req?.applicants ?? []) as { twin_id: string; stage: string; applied_at?: string; match_score?: number | null }[];
    const { data: candTwins } = applicants.length > 0
      ? await supabase.from("digital_twins").select("id, name, verified_skills").in("id", applicants.map((a) => a.twin_id))
      : { data: [] as never[] };
    const byId = new Map((candTwins ?? []).map((c) => [c.id, c]));
    candidates = applicants.map((a) => {
      const t = byId.get(a.twin_id) as { id: string; name: string; verified_skills: { name: string; proficiency: number; verification_rigor?: string }[] } | undefined;
      const stageStatus = a.stage === "rejected" ? "rejected" : a.stage === "selected" ? "expired" : a.stage === "final_round" || a.stage === "technical_interview" || a.stage === "screening" ? "active" : "invited";
      return {
        id: a.twin_id,
        name: t?.name ?? `Candidate ${a.twin_id.slice(0, 6)}`,
        status: stageStatus,
        applied_at: a.applied_at ?? undefined,
        match_score: a.match_score ?? null,
        skills: (t?.verified_skills ?? []).map((s) => ({
          name: s.name,
          proficiency: s.proficiency,
          verification_rigor: (s.verification_rigor ?? "low") as Person["skills"][number]["verification_rigor"],
        })),
      };
    });
  }

  const plan = planStaffing(scenarioInput, population, candidates);

  const { data: saved, error: saveErr } = await supabase
    .from("staffing_scenarios")
    .upsert(
      {
        org_id: caller.org_id,
        name: plan.scenario.name,
        input_snapshot: { ...plan.scenario, geography: plan.scenario.geography ?? null },
        assumptions: plan.assumptions,
        result: plan,
        created_by: caller.id,
      },
      { onConflict: "org_id,name" }
    )
    .select("id")
    .single();
  if (saveErr) return json({ error: "INTERNAL", message: saveErr.message }, 500);

  return json({
    ok: true,
    scenario_id: saved.id,
    scope: caller.role === "manager" ? "team" : "org",
    population_size: population.length,
    candidate_pipeline_size: caller.role === "manager" ? null : candidates.length,
    ...plan,
  });
});
